import {
  Award,
  BrainCircuit,
  CalendarClock,
  Check,
  ChevronRight,
  Flag,
  History as HistoryIcon,
  Plus,
  Sparkles,
  Target,
  Trash2,
  Trophy,
} from "lucide-react";
import api, { message } from "./api";

const money = (v) =>
  new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(v || 0);
const pretty = (v) =>
  (v || "").replaceAll("_", " ").replace(/\b\w/g, (c) => c.toUpperCase());
const riskTone = (r) => (r || "low").toLowerCase();
